  },
  AvgCommunicate_126998_Content_13 = {
    Text = "「私」、あるいは「私たち」――時間線上のすべての「ラモーナ」。"
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "あなたの力を借りて、私は「終端」に至ったその刹那、自分自身を「原点」へと上書きすることに成功したの。"
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "最初、私の予想はあなたと同じだった。パラドックスと歪みが一瞬で私の存在を飲み込み、そして絶え間ない自己回溯を繰り返すことで、辛うじて意識と形体を保つ――"
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "その後は永遠に疲弊の中で生き続け、一瞬一瞬、自分の概念が消散しないよう神経を張り詰めなければならない…………"
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "だから私は、あなたの最初の十九回の提案を拒否したの。"
  },
  AvgCommunicate_126998_Content_18 = {
