  },
  AvgCommunicate_126998_Content_19 = {
    Text = "ええ、でも計画が成功してから気づいたの。自己のパラドックスは思考と肉体の衝突から生じるもの。そしてとうに時間の大河を越えた存在にとっては…………"
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "多くを語る必要はありません、秘密の番人。"
