  },
  AvgCommunicate_134249_Content_11 = {
    Text = "秘密の守り手さん、私、病気なんでしょうか？胃がふにゃふにゃで、心臓もふにゃふにゃで、全部が柔らかくて、よく分からない、溶けてしまいそう…………"
