  },
  AvgCommunicate_134249_Content_18 = {
    Text = "秘密の守り手、これからはなるべくあなたのドアの前にしゃがみ込まないようにします。"
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "でも…………夜、たまに私のためにドアを開けておいてもらえませんか？窓でもいいです。"
