  AvgCommunicate_134249_Content_2 = {
    Text = "兄さんの血肉と私の体が、前よりずっと馴染むようになった。皮膚の下で静かに呼吸していて、もう私を引き裂こうと喚き続けることはない。"
  },
  AvgCommunicate_134249_Content_20 = {
