  },
  AvgCommunicate_134249_Content_3 = {
    Text = "血への渇望もそこまで痛くなくなった。前は喉に何かが詰まってるみたいで、飲まないと窒息しそうだった。今はなんだか…………少し待ってくれるようになった。"
