  },
  AvgCommunicate_134250_Content_2 = {
    Text = "成長した猛獣は鎖を引きちぎり、ガブッ――と飼い主の喉を噛み千切る。"
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "あなたが本当に私を裏切る日が来たら…………たとえ天の果てまで逃げても、追いかけて喉を噛み千切ってやる。"
