  },
  AvgCommunicate_134264_Content_5 = {
    Text = "衆生の苦しみをこの一身に集め、万物を苦難のない無垢なる浄土へと導く――これは重荷ではないわ。父神が私に授けてくださった恩寵なの。"
  },
  AvgCommunicate_134264_Content_6 = {
