  },
  AvgCommunicate_149986_Content_15 = {
    Text = "……まあ、公演では、お姫様を演じるジェンキンが空から降ってきて、王子様を演じるリリーが彼女を受け止めることになっています。"
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "魔王を演じるアイギスは舞台を降りて観客と交流するそうです。"
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "この配役についてはもうツッコむ気にもなれません……"
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "でも、これはネタバレになりませんか？"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "あなたに何も隠したくないからです。"
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "演劇部が童話劇を上演することになり、ミサゴの未成年の覚醒体たちを集めて共演することになりました。"
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "それに、稽古の様子を見ていると、毎回違うハプニングが起きていますので、主君が実際に何をご覧になるかは保証できません。"
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "……それは確かに気になりますね。"
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "演技中のこれらの行為は、多かれ少なかれ一定の危険性を伴っています。"
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "そのため、木を演じながらも、舞台上と客席の状況にできる限り気を配り、演者と観客の安全を確保する必要があります。"
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "つまり実はボディーガードの兼業をしに行っていたんですね……なかなか大変そうですね。"
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "ええ。いずれにせよ、ご安心ください。私が舞台にいる限り、二度と誰も傷つけさせません。"
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "少し言いづらいのですが……私も舞台に立ちます。ぜひご覧いただければと思います。"
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "！楽しみにしています。"
  },
  AvgCommunicate_149986_Content_5 = {
