  AvgCommunicate_149986_Content_6 = {
    Text = "ええ、私はもう子供ではありませんし、参加するのは適切ではないと思っていました。"
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "ですが、彼女たちがどうしてもと言い張って……"
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "興を削ぎたくありませんし、それに、この役は確かに私にしか務まらないと気づきました。"
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "それで、オジールはどんな役を演じるのですか？騎士ですか？"
