  },
  AvgCommunicate_149987_Content_11 = {
    Text = "そのようにお褒めにならないでください。あなたが担う責務の方が、私よりもずっと大変です。"
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "それに、これは罪を償うために必要な勉強に過ぎません。"
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "でも覚えるのが早いですね、もしかしたらオジールには学者になる素質があるかもしれませんよ。"
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "誰もが子供の頃に考えるような、将来についての話ですが。"
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "オジールは大きくなったら何をしたいと思ったことはありますか？"
