    Text = "やっぱりあなたは頼もしくて気が利く、わたくしの騎士よ。"
  },
  AvgCommunicate_66984_Content_2 = {
    Text = "これはこれは、ソレール夫人を困らせるなんて……どんな件でしょう？"
  },
  AvgCommunicate_66984_Content_3 = {
    Text = "喜んでお聞きします。"
  },
  AvgCommunicate_66984_Content_4 = {
    Text = "数日後、晩餐と舞踏会に参加する予定なの——わかるでしょ？気取っていて面倒な人たちが集まって、特にすることもない催しよ。"
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "困っているのは、最近しつこく私につきまとう礼儀知らずの人。彼も舞踏会に来るけど、堂々と私をエスコート役に指名してきたの。"
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "そんな厄介な奴が……排除してしまいましょうか、夫人？"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "ふふふ、冗談のセンスが磨かれてきたわね。"
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "残念ながら、今はまだ動けない。大人の世界って、そういう面倒がつきものなの。でも、もう招待は断ってあるから安心して。"
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "では、問題は解決したのではないのですか？"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "光栄です、夫人。"
  },
  AvgCommunicate_66984_Option_2 = {
    Text = "ソレール夫人を困らせるなんて……"
  },
  AvgCommunicate_66984_Option_3 = {
    Text = "喜んでお聞きします。"
  },
  AvgCommunicate_66984_Option_6 = {
    Text = "排除してしまいましょうか、夫人？"
  },
  AvgCommunicate_66984_Option_9 = {
    Text = "では、問題は解決したのではないのですか？"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "わたくしの小さな騎士。先日の舞踏会の助力のおかげで、ようやくあの厄介な相手を振り払うことができましたわ。"
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "願ってもいいなら……美しいソレール夫人とロマンチックなキャンドルディナーを。"
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "誰にも邪魔されず、ふたりきりで。"
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "ふふ、狡猾なお方ね。よろしいわ。"
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "何を食べたい？ちゃんと言ってね。私も隣で一緒に味わいたいの。"
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "では、学食の味しかしらない私は想像するだけでたいへんですが、夫人がふだん一番好きな料理を、私も食べてみたいです。"
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "ふふふ、ほんとに人の心を掴むのが上手なお方。"
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "それでは、わたくしの邸宅で——あなたのお越しを心よりお待ちしておりますわ。"
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "あなたの親切と寛容への感謝として——何か私から返礼をさせていただけないかしら。"
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "そんな、お気遣いなく。ソレール夫人。私たちの間柄に「感謝」の言葉はもう不要かと。"
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "ええ、口先だけの「ありがとう」なんて好きじゃないの。大体は、空々しい儀礼でしかありませんもの。"
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "でも、「何でも一つだけお願いしてもいい」って言われたら——興味、ないのかしら？"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "えっ、本当に「何でも」？そんなの貴族の旦那様方に聞かれたら、嫉妬で泡を吹くかもしれませんね。"
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "ふふ、あなたはそれだけ「特別」なのよ。"
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "これは本当に困りました……思い切って邸宅でもお願いしてみようか……でも学校にバレたらさすがにまずい……"
  },
  AvgCommunicate_66985_Content_9 = {
    Text = "大丈夫。すべてわたくしが処理するわ——遠慮せず、願いをひとつ。"
