  },
  AvgCommunicate_66986_Content_1 = {
    Text = "さっきロータンと一戦交えてきたの。引き分けだったわ。"
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "あはは……私はそんなに雑念ないと思うし、遠慮しとくよ……"
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "なら、君は君で強いのね。"
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "ただ、滝のそばにいつも釣り人がいて――ちょっと騒がしいの。"
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "この前なんか、滝から出て「静かにしなさい」って言ったら、驚いた彼に魚を顔面に投げつけられて逃げられたわ。"
