  AvgCommunicate_70501_Content_2 = {
    Text = "……君の顔の話？"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "その言葉……私にはとても大切なものよ。ありがとう、守秘者{Male=さん,Female=さん}。"
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "お礼に、小さな秘密をひとつ。君が夢に入ったとき、私はすぐ隣に立っていたの。"
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "あの、ちょっとばかり崩れた表情……ちゃんと彫り込んだわ。そっくりに、生々しく。"
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "暇ができたら、私のちいさな展示室に見に来てね〜"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "サンガー！君に50スタールを渡すから、どうかその彫刻だけは処分して……！！"
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "でも、あれこそ君がさっき言ったでしょう？——「生き生きとして、残酷」な芸術だって。ねえ、守秘者？"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "もちろん、夢の中で君が見た彫刻の話よ。"
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "肉体の線は自然で調和が取れていたけれど——静けさの中に宿る永遠の美が欠けていたわ。主題も創意もまだ足りない。彫刻には、もっと命が要るの。"
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "あの一連の彫刻、もうほとんど誰も見たことがない。君の感想を聞かせて。"
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "あれって……君の作品？"
  },
  AvgCommunicate_70501_Content_7 = {
