  AvgCommunicate_70514_Content_10 = {
    Text = "彼女に守られていたからこそ、私は安心して花と詩の世界を彷徨うことができました。"
  },
  AvgCommunicate_70514_Content_11 = {
    Text = "守られていたことも、傷つけられたことも……今はもう、全部、過去のことです。"
  },
  AvgCommunicate_70514_Content_12 = {
    Text = "……この前、一緒にシディ島に行ってくれてありがとうございました。あの旅は……とても大事な時間になりました。"
  },
  AvgCommunicate_70514_Content_13 = {
