  AvgCommunicate_70523_Content_1 = {
    Text = "急な道中で、皆さんにこちらの風土についてご案内もできませんでしたね。"
  },
  AvgCommunicate_70523_Content_10 = {
    Text = "前にもお伝えしました通り、私はただ、司教の教義を伝える使者です。"
  },
  AvgCommunicate_70523_Content_11 = {
    Text = "私たちの神は、世界により良い未来を創造するでしょう。"
  },
  AvgCommunicate_70523_Content_12 = {
    Text = "アランのような古き部族も、その未来の一部であり、忠実なる友人なのです。"
  },
  AvgCommunicate_70523_Content_13 = {
    Text = "もちろん、守秘者{Male=さん,Female=さん}のご不安も理解しています。"
  },
  AvgCommunicate_70523_Content_14 = {
    Text = "もう少し関わっていただければ、その疑念も自然に薄れてゆくでしょう。"
  },
  AvgCommunicate_70523_Content_15 = {
    Text = "長旅でお疲れでしょう。ごゆっくりお休みください。"
  },
  AvgCommunicate_70523_Content_16 = {
    Text = "ヴォルムワヒを代表し、心よりあなたの到来を歓迎します、守秘者{Male=さん,Female=さん}。"
  },
  AvgCommunicate_70523_Content_2 = {
    Text = "守秘者{Male=さん,Female=さん}、ご質問などございましたら、私が代わってお答えしますよ。"
  },
  AvgCommunicate_70523_Content_3 = {
    Text = "私はこの地の風習には少し興味があります。"
  },
  AvgCommunicate_70523_Content_4 = {
    Text = "アラン族は世代を超えて放牧で生計を立て、工業社会から離れていますが、野蛮で未開な部族だなんて、思わないでくださいね。"
  },
  AvgCommunicate_70523_Content_5 = {
    Text = "ここには厳格な規範もありません。自由に交流されて大丈夫ですよ。"
  },
  AvgCommunicate_70523_Content_6 = {
    Text = "アランの人々の温かさは、きっとすぐに感じていただけます。"
  },
  AvgCommunicate_70523_Content_7 = {
    Text = "このような牧歌的な部族の中に、ジュリエット使者のような方がいるのが、少し奇妙に思います。そうでもないですか？"
  },
  AvgCommunicate_70523_Content_8 = {
    Text = "「夢のお告げでアランへ導かれた」って……その理由に少し無理があるように思えます。"
  },
  AvgCommunicate_70523_Content_9 = {
    Text = "守秘者{Male=さん,Female=さん}、ご心配には及びません。"
  },
  AvgCommunicate_70523_Option_3 = {
    Text = "私はこの地の風習には少し興味があります。"
  },
  AvgCommunicate_70523_Option_7 = {
    Text = "私はジュリエット使者自身に興味があります。"
  },
  AvgCommunicate_70524_Content_1 = {
    Text = "そういえば……蝋人形館の事件以来、我々が直接組むのは久しぶりだな。"
  },
  AvgCommunicate_70524_Content_10 = {
    Text = "今回の共闘がうまくいくといいな。"
  },
  AvgCommunicate_70524_Content_11 = {
