  },
  AvgCommunicate_70524_Content_2 = {
    Text = "前回の海踊人の件でも、ウィリアム先輩はかなり助けてくれたじゃないですか！"
  },
  AvgCommunicate_70524_Content_3 = {
    Text = "……ただ車を運転しただけで、助けたうちには入らない。"
