  AvgCommunicate_81324_Content_11 = {
    Text = "その通り。考えてもみてよ。私が君にあの二つの課題をさせたのは、君を利用してタダ働きをさせたいからか、それとも君に学問の機会を得てほしいからか。どちらだと思う？"
