  },
  AvgCommunicate_81324_Content_20 = {
    Text = "そうか、恩人殿は本当に道徳的な方なのだな！では、恩人殿の課題をあと何冊か俺に与えてくれ。真剣にやり遂げてから、また教えを請いに来よう。"
