  AvgCommunicate_94500_Content_1 = {
    Text = "御身の教えにより、オジール殿と知り合うことができ、さらに多くの友人を紹介していただいた。"
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "オジール殿曰く、騎士の訓練はこれよりもさらに複雑で厳しいのだとか。写本に書かれていたとおり、騎士とは皆、心より尊敬すべき人々なのだな。"
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "確かに、オジールは覚醒体の中でも、特に訓練に熱心だからね！"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "教官であるアルバ殿も、体に不自由があろうと、我らと同じ訓練をこなしておられた。"
