  AvgCommunicate_94500_Content_13 = {
    Text = "我らはアルバ教官も騎士だと思っておったが、彼女は元軍人だと仰っていた。軍人とはどのような職業なのかは分からぬが、騎士と同じく尊敬すべき存在なのだろうな。"
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "軍人は国のために戦う人たちのことで、騎士の一種と言えるかもしれない。でも、騎士の厳格な道徳律に比べると、その行いが必ずしも正義を表しているとは限らない。"
  },
  AvgCommunicate_94500_Content_15 = {
